package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaims {
    public void respond(@Val Sheet sheet, @Val List<Claim> claims, ClaimLogRepository logs, ClaimLockRepository locks,
            ClaimRepository repository, ClaimCommentRepository comments, ClaimLineRepository lines, SettleBatchRepository batches,
            ClaimShareRepository shares,
            ObjectResponse<List<ClaimResponse>> response) {
        Map<Long, List<ClaimLogLine>> log = logs.findAll(sheet.id());
        Map<Long, String> locked = locks.findAll(sheet.id());
        Set<Long> late = repository.lateEntries(sheet.id());
        Map<Long, LocalDate> reminded = repository.remindedAll(sheet.id());
        Map<Long, String> refs = repository.refs(sheet.id());
        Map<Long, String> tags = repository.tagsAll(sheet.id());
        Map<Long, String> voidReasons = repository.voidReasons(sheet.id());
        Map<Long, Integer> batched = batches.batches(sheet.id());
        Map<Long, List<ClaimComment>> commented = comments.findAll(sheet.id());
        Map<Long, List<ClaimLine>> lined = lines.findAll(sheet.id());
        Map<Long, Integer> photos = repository.photoProofsAll(sheet.id());
        Map<Long, List<ClaimShare>> shared = shares.findAll(sheet.id());
        Map<Long, String> assignees = repository.reviewAssignees(sheet.id());
        response.send(claims.stream()
                .map((c) -> ClaimResponse.from(c, log.getOrDefault(c.id(), List.of()), locked.get(c.id()),
                        late.contains(c.id()), reminded.get(c.id()), refs.get(c.id()),
                        tags.get(c.id()), voidReasons.get(c.id()),
                        commented.getOrDefault(c.id(), List.of()), batched.get(c.id()),
                        lined.getOrDefault(c.id(), List.of()), photos.getOrDefault(c.id(), 0),
                        shared.getOrDefault(c.id(), List.of()), assignees.get(c.id()))).toList());
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import type { Claim } from './claims';
import { claimsKey } from './claims';
import { useOneAtATime } from '../../query/useOneAtATime';
import { useClaimError } from './claimError';

// The people the claim is shared with, as `<name> <share>` in the order given, and the entries to share it: a person and
// a percent of its due (two decimals, more than 0.00). Each holder's due-total counts their part, the claim's own
// person's the rest. The server refuses the claim's own person, a person already holding a share, shares above 100.00
// in all, and a SETTLED, VOID or DELETED claim; the refusal shows as the claim's error.
export function ClaimShares({ claim }: { claim: Claim }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setError] = useClaimError(claim.id);
  const people = usePeople().data ?? [];
  const [personId, setPersonId] = useState('');
  const [share, setShare] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (body: { personId: number; share: string }) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/shares?user=${encodeURIComponent(user)}`, body),
    onSuccess: async () => {
      setPersonId('');
      setShare('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        'This claim cannot be shared so (not with its own person or a holder again, shares at most 100.00 in all, more than 0.00 each, and not a SETTLED, VOID or DELETED claim).',
      ),
  });

  const nameOf = (id: number) => people.find((p) => p.id === id)?.name ?? '';
